-- Community records are separate from banked study history and camera previews.
create table public.community_admins(user_id uuid primary key references public.profiles(id) on delete cascade);
create table public.user_blocks(blocker_id uuid references public.profiles(id) on delete cascade,blocked_id uuid references public.profiles(id) on delete cascade,created_at timestamptz not null default now(),primary key(blocker_id,blocked_id),check(blocker_id<>blocked_id));
create table public.study_groups(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles(id),name text not null check(length(name) between 1 and 100),description text not null default '' check(length(description)<=2000),is_private boolean not null default false,created_at timestamptz not null default now());
create table public.group_members(group_id uuid references public.study_groups(id) on delete cascade,user_id uuid references public.profiles(id) on delete cascade,role text not null default 'member' check(role in ('owner','moderator','member')),accepted boolean not null default false,created_at timestamptz not null default now(),primary key(group_id,user_id));
create table public.study_rooms(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles(id),group_id uuid references public.study_groups(id),name text not null check(length(name) between 1 and 100),description text not null default '' check(length(description)<=1000),category text not null default 'deep' check(category in ('pomodoro','deep','chill','cram')),is_private boolean not null default false,capacity integer not null default 12 check(capacity between 1 and 1000),is_closed boolean not null default false,created_at timestamptz not null default now());
create table public.room_members(room_id uuid references public.study_rooms(id) on delete cascade,user_id uuid references public.profiles(id) on delete cascade,role text not null default 'member' check(role in ('owner','moderator','member')),primary key(room_id,user_id));
create table public.room_visits(id uuid primary key default gen_random_uuid(),room_id uuid not null references public.study_rooms(id),user_id uuid not null references public.profiles(id),joined_at timestamptz not null default now(),last_seen_at timestamptz not null default now(),left_at timestamptz,sharing_video boolean not null default false,status_message text not null default '' check(length(status_message)<=200),check(left_at is null or left_at>=joined_at));
create unique index room_visit_active_user on public.room_visits(user_id) where left_at is null;
create index room_visits_room_active on public.room_visits(room_id,last_seen_at) where left_at is null;
create index room_visits_overlap on public.room_visits(room_id,joined_at,left_at);
create table public.room_invites(id uuid primary key default gen_random_uuid(),room_id uuid not null references public.study_rooms(id) on delete cascade,created_by uuid not null references public.profiles(id),token_hash text not null unique,expires_at timestamptz not null,remaining_uses integer not null check(remaining_uses>=0));
create table public.room_pins(user_id uuid references public.profiles(id) on delete cascade,room_id uuid references public.study_rooms(id) on delete cascade,target_id uuid references public.profiles(id) on delete cascade,reason text not null default '' check(length(reason)<=200),primary key(user_id,room_id,target_id));
create table public.partner_preferences(user_id uuid references public.profiles(id) on delete cascade,partner_id uuid references public.profiles(id) on delete cascade,is_favorite boolean not null default false,notify boolean not null default false,primary key(user_id,partner_id),check(user_id<>partner_id));
create table public.buddy_listings(id uuid primary key default gen_random_uuid(),owner_id uuid not null unique references public.profiles(id) on delete cascade,title text not null check(length(title) between 1 and 100),body text not null check(length(body) between 1 and 4000),subjects text[] not null default '{}',is_published boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.conversation_threads(id uuid primary key default gen_random_uuid(),owner_id uuid references public.profiles(id),group_id uuid references public.study_groups(id),kind text not null check(kind in ('channel','direct','group')),title text not null check(length(title) between 1 and 100),read_only boolean not null default false,created_at timestamptz not null default now());
create table public.thread_members(thread_id uuid references public.conversation_threads(id) on delete cascade,user_id uuid references public.profiles(id) on delete cascade,primary key(thread_id,user_id));
create table public.chat_messages(id uuid primary key default gen_random_uuid(),thread_id uuid not null references public.conversation_threads(id),author_id uuid not null references public.profiles(id),parent_id uuid references public.chat_messages(id),client_id uuid not null,body text not null check(length(body) between 1 and 4000),is_deleted boolean not null default false,created_at timestamptz not null default now(),edited_at timestamptz,unique(author_id,client_id));
create index chat_thread_created on public.chat_messages(thread_id,created_at,id);
create table public.saved_messages(user_id uuid references public.profiles(id) on delete cascade,message_id uuid references public.chat_messages(id) on delete cascade,primary key(user_id,message_id));
create table public.feed_posts(id uuid primary key default gen_random_uuid(),author_id uuid not null references public.profiles(id),group_id uuid references public.study_groups(id),parent_id uuid references public.feed_posts(id),body text not null check(length(body) between 1 and 4000),attachments jsonb not null default '[]' check(jsonb_typeof(attachments)='array' and jsonb_array_length(attachments)<=4),is_deleted boolean not null default false,created_at timestamptz not null default now(),edited_at timestamptz);
create index feed_created on public.feed_posts(created_at desc,id desc);
create table public.post_reactions(user_id uuid references public.profiles(id) on delete cascade,post_id uuid references public.feed_posts(id) on delete cascade,emoji text not null check(emoji in ('heart','support','celebrate')),primary key(user_id,post_id));
create table public.saved_posts(user_id uuid references public.profiles(id) on delete cascade,post_id uuid references public.feed_posts(id) on delete cascade,primary key(user_id,post_id));
create table public.scheduled_sessions(id uuid primary key default gen_random_uuid(),creator_id uuid not null references public.profiles(id),room_id uuid not null unique references public.study_rooms(id),title text not null check(length(title) between 1 and 100),starts_at timestamptz not null,minutes integer not null check(minutes in (30,60)),capacity integer not null check(capacity between 1 and 1000),is_cancelled boolean not null default false,created_at timestamptz not null default now());
create table public.session_bookings(event_id uuid references public.scheduled_sessions(id) on delete cascade,user_id uuid references public.profiles(id) on delete cascade,created_at timestamptz not null default now(),primary key(event_id,user_id));
create table public.study_tasks(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,title text not null check(length(title) between 1 and 300),due_date date not null,is_done boolean not null default false,created_at timestamptz not null default now());
create table public.app_notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,actor_id uuid references public.profiles(id) on delete cascade,kind text not null check(kind in ('follow','message','booking','cancelled','membership')),resource_id uuid,is_read boolean not null default false,created_at timestamptz not null default now());
create table public.community_reports(id uuid primary key default gen_random_uuid(),reporter_id uuid not null references public.profiles(id),target_kind text not null check(target_kind in ('person','post','message','buddy','room','group')),target_id uuid not null,reason text not null check(length(reason) between 1 and 1000),status text not null default 'open' check(status in ('open','reviewed','resolved')),created_at timestamptz not null default now());
create table public.app_feedback(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id),kind text not null check(kind in ('issue','idea')),body text not null check(length(body) between 1 and 4000),created_at timestamptz not null default now());
create table public.plan_policies(plan text primary key,daily_room_seconds integer check(daily_room_seconds>=0),max_pins integer check(max_pins>=0),partner_rows integer check(partner_rows>=0));
insert into public.plan_policies(plan) values('free'); -- Limits stay unconfigured until the product owner sets them.
create table public.account_entitlements(user_id uuid primary key references public.profiles(id) on delete cascade,plan text not null references public.plan_policies(plan),expires_at timestamptz);
alter table public.profiles add column leaderboard_opt_in boolean not null default false;
grant update(leaderboard_opt_in) on public.profiles to authenticated;
create table public.leaderboard_snapshots(snapshot_at timestamptz not null,metric text not null,period text not null,user_id uuid not null references public.profiles(id) on delete cascade,score bigint not null,rank integer not null,primary key(snapshot_at,metric,period,user_id));
create index leaderboard_snapshot_rank on public.leaderboard_snapshots(snapshot_at,metric,period,rank,user_id);

create function auth_private.community_admin(actor uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.community_admins where user_id=actor);$$;
create function auth_private.is_blocked(a uuid,b uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.user_blocks where (blocker_id=a and blocked_id=b) or(blocker_id=b and blocked_id=a));$$;
create function auth_private.group_member(g uuid,actor uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.group_members where group_id=g and user_id=actor and accepted);$$;
create function auth_private.group_manager(g uuid,actor uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.group_members where group_id=g and user_id=actor and accepted and role in ('owner','moderator'));$$;
create function auth_private.can_read_group(g uuid,actor uuid) returns boolean language sql stable security definer set search_path='' as $$select actor is not null and exists(select 1 from public.study_groups where id=g and (not is_private or auth_private.group_member(g,actor)));$$;
create function auth_private.can_read_room(r uuid,actor uuid) returns boolean language sql stable security definer set search_path='' as $$select actor is not null and exists(select 1 from public.study_rooms where id=r and not is_closed and (group_id is null or auth_private.group_member(group_id,actor)) and (not is_private or owner_id=actor or exists(select 1 from public.room_members where room_id=r and user_id=actor)));$$;
create function auth_private.can_read_thread(t uuid,actor uuid) returns boolean language sql stable security definer set search_path='' as $$select actor is not null and exists(select 1 from public.conversation_threads where id=t and ((kind='channel' and group_id is null) or (group_id is not null and auth_private.group_member(group_id,actor)) or exists(select 1 from public.thread_members where thread_id=t and user_id=actor)));$$;
create function auth_private.can_read_post(p uuid,actor uuid) returns boolean language sql stable security definer set search_path='' as $$select actor is not null and exists(select 1 from public.feed_posts where id=p and not is_deleted and not auth_private.is_blocked(author_id,actor) and (group_id is null or auth_private.group_member(group_id,actor)));$$;
create function auth_private.active_room_member(r uuid,actor uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.room_visits where room_id=r and user_id=actor and left_at is null and last_seen_at>now()-interval '90 seconds');$$;
create function auth_private.leaderboard_consent(actor uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.profiles where id=actor and leaderboard_opt_in);$$;

-- Explicit row access on every table. All writes use the closed RPC below.
do $$declare table_name text; begin
foreach table_name in array array['community_admins','user_blocks','study_groups','group_members','study_rooms','room_members','room_visits','room_invites','room_pins','partner_preferences','buddy_listings','conversation_threads','thread_members','chat_messages','saved_messages','feed_posts','post_reactions','saved_posts','scheduled_sessions','session_bookings','study_tasks','app_notifications','community_reports','app_feedback','plan_policies','account_entitlements','leaderboard_snapshots'] loop
  execute format('alter table public.%I enable row level security',table_name);
  execute format('revoke all on public.%I from public,anon,authenticated',table_name);
  execute format('grant select on public.%I to authenticated',table_name);
end loop;
end;$$;
create policy admin_self on public.community_admins for select to authenticated using(user_id=(select auth.uid()));
create policy blocks_self on public.user_blocks for select to authenticated using(blocker_id=(select auth.uid()));
create policy groups_visible on public.study_groups for select to authenticated using(auth_private.can_read_group(id,(select auth.uid())));
create policy group_members_visible on public.group_members for select to authenticated using(user_id=(select auth.uid()) or auth_private.group_member(group_id,(select auth.uid())));
create policy rooms_visible on public.study_rooms for select to authenticated using(auth_private.can_read_room(id,(select auth.uid())));
create policy room_members_visible on public.room_members for select to authenticated using(user_id=(select auth.uid()) or auth_private.can_read_room(room_id,(select auth.uid())));
create policy visits_visible on public.room_visits for select to authenticated using(user_id=(select auth.uid()) or (left_at is null and last_seen_at>now()-interval '90 seconds' and auth_private.active_room_member(room_id,(select auth.uid()))));
create policy invites_owner on public.room_invites for select to authenticated using(created_by=(select auth.uid()));
create policy pins_self on public.room_pins for select to authenticated using(user_id=(select auth.uid()));
create policy partners_self on public.partner_preferences for select to authenticated using(user_id=(select auth.uid()));
create policy buddies_visible on public.buddy_listings for select to authenticated using((is_published or owner_id=(select auth.uid())) and not auth_private.is_blocked(owner_id,(select auth.uid())));
create policy threads_visible on public.conversation_threads for select to authenticated using(auth_private.can_read_thread(id,(select auth.uid())));
create policy thread_members_visible on public.thread_members for select to authenticated using(auth_private.can_read_thread(thread_id,(select auth.uid())));
create policy messages_visible on public.chat_messages for select to authenticated using(auth_private.can_read_thread(thread_id,(select auth.uid())) and not auth_private.is_blocked(author_id,(select auth.uid())));
create policy saved_messages_self on public.saved_messages for select to authenticated using(user_id=(select auth.uid()));
create policy posts_visible on public.feed_posts for select to authenticated using(auth_private.can_read_post(id,(select auth.uid())));
create policy reactions_visible on public.post_reactions for select to authenticated using(auth_private.can_read_post(post_id,(select auth.uid())));
create policy saved_posts_self on public.saved_posts for select to authenticated using(user_id=(select auth.uid()));
create policy schedules_visible on public.scheduled_sessions for select to authenticated using(auth_private.can_read_room(room_id,(select auth.uid())));
create policy bookings_self on public.session_bookings for select to authenticated using(user_id=(select auth.uid()) or exists(select 1 from public.scheduled_sessions where id=event_id and creator_id=(select auth.uid())));
create policy tasks_self on public.study_tasks for select to authenticated using(user_id=(select auth.uid()));
create policy notifications_self on public.app_notifications for select to authenticated using(user_id=(select auth.uid()));
create policy reports_self on public.community_reports for select to authenticated using(reporter_id=(select auth.uid()) or auth_private.community_admin((select auth.uid())));
create policy feedback_self on public.app_feedback for select to authenticated using(user_id=(select auth.uid()) or auth_private.community_admin((select auth.uid())));
create policy plan_read on public.plan_policies for select to authenticated using(true);
create policy entitlement_self on public.account_entitlements for select to authenticated using(user_id=(select auth.uid()));
create policy leaderboard_consent on public.leaderboard_snapshots for select to authenticated using(auth_private.leaderboard_consent(user_id));

-- No secrets, fictitious users or demo activity are seeded.
insert into public.conversation_threads(kind,title,read_only) values('channel','general',false),('channel','announcements',true),('channel','contact-and-guidelines',true),('channel','feature-requests',false);
grant usage on schema auth_private to authenticated;
grant execute on function auth_private.community_admin(uuid),auth_private.is_blocked(uuid,uuid),auth_private.group_member(uuid,uuid),auth_private.group_manager(uuid,uuid),auth_private.can_read_group(uuid,uuid),auth_private.can_read_room(uuid,uuid),auth_private.can_read_thread(uuid,uuid),auth_private.can_read_post(uuid,uuid) to authenticated;
revoke all on function auth_private.community_admin(uuid),auth_private.is_blocked(uuid,uuid),auth_private.group_member(uuid,uuid),auth_private.group_manager(uuid,uuid),auth_private.can_read_group(uuid,uuid),auth_private.can_read_room(uuid,uuid),auth_private.can_read_thread(uuid,uuid),auth_private.can_read_post(uuid,uuid) from public,anon;
revoke all on function auth_private.active_room_member(uuid,uuid),auth_private.leaderboard_consent(uuid) from public,anon;
grant execute on function auth_private.active_room_member(uuid,uuid),auth_private.leaderboard_consent(uuid) to authenticated;
